[ExcludeFromCodeCoverage]
public sealed class SupportedCultures : ReadOnlyCollection<CultureInfo>
{
    public static readonly SupportedCultures Default = new(CultureInfo.CurrentCulture);

    public SupportedCultures(CultureInfo parent)
        : base(new[] { parent })
    {
        Parent = parent;
    }

    public SupportedCultures(
        CultureInfo parent,
        IList<CultureInfo> list)
        : base(list)
    {
        Parent = parent;
    }

    public CultureInfo Parent { get; }
}

using Microsoft.AspNetCore.Localization;
using Microsoft.Net.Http.Headers;

namespace RedisToggler.Api;

public sealed class SupportedRequestCultureProvider : AcceptLanguageHeaderRequestCultureProvider
{
    private const string AllCulturesSymbol = "*";

    public override Task<ProviderCultureResult?> DetermineProviderCultureResult(HttpContext httpContext)
    {
        var acceptLanguageHeader = httpContext.Request.Headers[HeaderNames.AcceptLanguage];
        if (acceptLanguageHeader.SequenceEqual(new[] { AllCulturesSymbol }))
        {
            var result = new ProviderCultureResult("all");
            return Task.FromResult<ProviderCultureResult?>(result);
        }

        return base.DetermineProviderCultureResult(httpContext);
    }
}

using Microsoft.AspNetCore.Mvc.ApiExplorer;
using Microsoft.OpenApi.Models;
using Swashbuckle.AspNetCore.SwaggerGen;
using System.Text.Json;

namespace RedisToggler.Api;

/// <summary>
/// Represents the Swagger/Swashbuckle operation filter used to document the implicit API version parameter.
/// </summary>
/// <remarks>This <see cref="IOperationFilter"/> is only required due to bugs in the <see cref="SwaggerGenerator"/>.
/// Once they are fixed and published, this class can be removed.</remarks>
public class SwaggerDefaultValues : IOperationFilter
{
    /// <summary>
    /// Applies the filter to the specified operation using the given context.
    /// </summary>
    /// <param name="operation">The operation to apply the filter to.</param>
    /// <param name="context">The current operation filter context.</param>
    public void Apply(OpenApiOperation operation, OperationFilterContext context)
    {
        var apiDescription = context.ApiDescription;

        operation.Deprecated |= apiDescription.IsDeprecated();

        // REF: https://github.com/domaindrivendev/Swashbuckle.AspNetCore/issues/1752#issue-663991077
        foreach (var responseType in context.ApiDescription.SupportedResponseTypes)
        {
            // REF: https://github.com/domaindrivendev/Swashbuckle.AspNetCore/blob/b7cf75e7905050305b115dd96640ddd6e74c7ac9/src/Swashbuckle.AspNetCore.SwaggerGen/SwaggerGenerator/SwaggerGenerator.cs#L383-L387
            var responseKey = responseType.IsDefaultResponse ? "default" : responseType.StatusCode.ToString();
            var response = operation.Responses[responseKey];

            foreach (var contentType in response.Content.Keys)
            {
                if (!responseType.ApiResponseFormats.Any(x => x.MediaType == contentType))
                {
                    response.Content.Remove(contentType);
                }
            }
        }

        if (operation.Parameters == null)
        {
            return;
        }

        // REF: https://github.com/domaindrivendev/Swashbuckle.AspNetCore/issues/412
        // REF: https://github.com/domaindrivendev/Swashbuckle.AspNetCore/pull/413
        foreach (var parameter in operation.Parameters)
        {
            var description = apiDescription.ParameterDescriptions.First(p => p.Name == parameter.Name);

            if (parameter.Description == null)
            {
                parameter.Description = description.ModelMetadata?.Description;
            }

            if (parameter.Schema.Default == null && description.DefaultValue != null)
            {
                // REF: https://github.com/Microsoft/aspnet-api-versioning/issues/429#issuecomment-605402330
                var json = JsonSerializer.Serialize(description.DefaultValue, description.ModelMetadata!.ModelType);
                parameter.Schema.Default = OpenApiAnyFactory.CreateFromJson(json);
            }

            parameter.Required |= description.IsRequired;
        }
    }
}

using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Options;
using RedisToggler.Api.Swagger;
using Swashbuckle.AspNetCore.SwaggerGen;

namespace RedisToggler.Api;

public static class SwashbuckleConfigExtension
{
    public static IServiceCollection ConfigSwashbuckle(this IServiceCollection services) =>
        services
            .AddEndpointsApiExplorer()
            .AddApiVersioning(options =>
            {
                options.ReportApiVersions = true;
                options.AssumeDefaultVersionWhenUnspecified = true;
                options.DefaultApiVersion = new ApiVersion(1, 0);
            })
            .AddVersionedApiExplorer(options =>
            {
                options.GroupNameFormat = "'version - v'VVV";
                options.SubstituteApiVersionInUrl = true;
            })
            .AddTransient<IConfigureOptions<SwaggerGenOptions>, ConfigureSwaggerOptions>()
            .AddSwaggerGen(options =>
            {
                options.OperationFilter<SwaggerDefaultValues>();
                options.OperationFilter<ApplicationHeaders>();
            });

    public static void LoadDocumentationFiles(this SwaggerGenOptions options)
    {
        foreach (var assembly in AppDomain.CurrentDomain.GetAssemblies())
        {
            var xmlDocumentationFile = $"{assembly.GetName().Name}.xml";
            var xmlDocumentationPath = Path.Combine(AppContext.BaseDirectory, xmlDocumentationFile);
            if (File.Exists(xmlDocumentationPath))
            {
                options.IncludeXmlComments(xmlDocumentationPath, includeControllerXmlComments: true);
            }
        }
    }
}

