using Microsoft.AspNetCore.Mvc;
using RedisToggler.Lib.Configurations;
using RedisToggler.Lib.Handlers;

namespace RedisToggler.Api.Controllers;

[ApiController]
[Route("[controller]")]
public class WeatherForecastController : ControllerBase
{
    private static readonly string[] Summaries = new[]
    {
        "Freezing", "Bracing", "Chilly", "Cool", "Mild", "Warm", "Balmy", "Hot", "Sweltering", "Scorching"
    };

    private readonly ILogger<WeatherForecastController> _logger;
    private readonly IDistributedTypedCache<CacheEntryConfiguration> _cache;

    public WeatherForecastController(
        ILogger<WeatherForecastController> logger,
        IDistributedTypedCache<CacheEntryConfiguration> cache)
    {
        _logger = logger;
        _cache = cache;
    }

    [HttpGet(Name = "GetWeatherForecast")]
    public async Task<IEnumerable<WeatherForecast>> GetAsync([FromQuery] bool fromCache)
    {
        const string key = "c3eed152-558b-42c1-93d8-9b87799b6aba";

        var obj = Enumerable.Range(1, 5).Select(index => new WeatherForecast
        {
            Date = DateTime.Now.AddDays(index),
            TemperatureC = Random.Shared.Next(-20, 55),
            Summary = Summaries[Random.Shared.Next(Summaries.Length)]
        })
        .ToArray();

        if (fromCache)
        {
            obj = await _cache.GetAsync(key, () => Task.FromResult(obj)!);
            await _cache.SetAsync(key, obj);
        }
        _logger.LogInformation("WeatherForecast retrieved.");
        return obj!;
    }
}

using Microsoft.AspNetCore.Localization;
using Microsoft.Extensions.Options;
using RedisToggler.Api;
using RedisToggler.Lib.Abstractions;
using RedisToggler.Lib.Configurations;
using RedisToggler.Lib.Extensions;
using System.Globalization;

CultureInfo _allCulturesCulture = new("all");

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.

builder.Services
    .AddControllers().Services
    .ConfigSwashbuckle();
// Learn more about configuring Swagger/OpenAPI at https://aka.ms/aspnetcore/swashbuckle
builder.Services
    .AddLocalization()
    .Configure<RequestLocalizationOptions>(options =>
    {
        var supportedCultures = new CultureInfo[]
        {
            new CultureInfo("pt-BR"),
            new CultureInfo("en"),
            new CultureInfo("es"),
        };
        options.SetDefaultCulture("pt-BR");
        options.SupportedCultures = supportedCultures;
        options.SupportedUICultures = supportedCultures;
        options.ApplyCurrentCultureToResponseHeaders = true;
        options.RequestCultureProviders.Clear();
        options.RequestCultureProviders.Add(new SupportedRequestCultureProvider());
    })
    .AddScoped(provider =>
    {
        var contextAccessor = provider.GetRequiredService<IHttpContextAccessor>();
        if (contextAccessor.HttpContext is null)
        {
            return SupportedCultures.Default;
        }

        var cultureFeature = contextAccessor.HttpContext!.Features.Get<IRequestCultureFeature>();
        var requestCulture = cultureFeature!.RequestCulture.Culture;
        if (requestCulture.Equals(_allCulturesCulture))
        {
            var localizationOptions = provider.GetRequiredService<IOptions<RequestLocalizationOptions>>().Value;
            var supportedCultures = localizationOptions.SupportedCultures!.ToArray();

            return new SupportedCultures(
                parent: requestCulture,
                list: supportedCultures[..^1]);
        }

        return new SupportedCultures(requestCulture);
    })
    .AddSingleton(opt => new CacheEntryConfiguration()
    {
        StoreLanguage = true,
    })
    .AddCacheWrapper(opt =>
    {
        // opt.ConnectionString = "redis-server.redis-server.svc.cluster.local:6379,asyncTimeout=1000,connectTimeout=1000,password=eYVX7EwVmmxKPCDmwMtyKVge8oLd2t81,abortConnect=false";
        opt.ConnectionString = "redis.home.arpa:6379,asyncTimeout=1000,connectTimeout=1000,password=eYVX7EwVmmxKPCDmwMtyKVge8oLd2t81,abortConnect=false";
        opt.CacheType = CacheType.Redis;
    });

var app = builder.Build();

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    var pathBase = builder.Configuration.GetValue<string>("ASPNETCORE_BASEURL") ?? "/";
    app.UsePathBase(pathBase);
    app.ConfigureSwagger(pathBase);
}

app.UseRequestLocalization(app.Services.GetRequiredService<IOptions<RequestLocalizationOptions>>()!.Value);
app.UseAuthorization();

app.MapControllers();

await app.RunAsync();
